/bin/bash -lc "python - <<'PY'
import csv, json, math
from collections import defaultdict, Counter

TOL=1e-6
BIGTOL=1e-4

# Load data
with open('/app/data/config.json') as f:
    config=json.load(f)

def load_csv(path,key=None):
    with open(path,newline='') as f:
        rows=list(csv.DictReader(f))
    if key:
        return {tuple(r[k] for k in key): r for r in rows}
    return rows

time_rows=load_csv('/app/data/time_periods.csv')
gen_rows=load_csv('/app/data/generators.csv')
stor_rows=load_csv('/app/data/storage_units.csv')
ev_rows=load_csv('/app/data/ev_clusters.csv')
ren_rows=load_csv('/app/data/renewable_forecast.csv')
grid_rows=load_csv('/app/data/grid_limits.csv')
dr_rows=load_csv('/app/data/demand_response.csv')
scen_rows=load_csv('/app/data/scenarios.csv')
sh_rows=load_csv('/app/data/scenario_hourly.csv')
sol_rows=load_csv('/app/submissions/solution.csv')

hours=sorted(int(r['hour']) for r in time_rows)
scenarios=[r['scenario_id'] for r in scen_rows]
G=[r['generator_id'] for r in gen_rows]
B=[r['storage_id'] for r in stor_rows]
E=[r['cluster_id'] for r in ev_rows]
R=['pv','wind']
row_assets={
    'generator': G,
    'storage': B,
    'ev_cluster': E,
    'grid': ['grid'],
    'renewable': R,
    'demand_response': ['flex_load'],
    'load_shed': ['critical_load'],
}

# maps with numeric conversion
base={int(r['hour']):{k:(float(v) if k"'!='"'hour' else int(v)) for k,v in r.items()} for r in time_rows}
ren={int(r['hour']):{'pv':float(r['pv_kw']),'wind':float(r['wind_kw'])} for r in ren_rows}
grid={int(r['hour']):float(r['import_cap_kw']) for r in grid_rows}
dr={int(r['hour']): {'max_curtail_kw':float(r['max_curtail_kw']),'rebound_hour':int(r['rebound_hour']),'rebound_fraction':float(r['rebound_fraction']),'discomfort_cost_per_kwh':float(r['discomfort_cost_per_kwh'])} for r in dr_rows}
scenh={(r['scenario_id'],int(r['hour'])):{
    'load_multiplier':float(r['load_multiplier']),
    'pv_multiplier':float(r['pv_multiplier']),
    'wind_multiplier':float(r['wind_multiplier']),
    'grid_import_multiplier':float(r['grid_import_multiplier']),
    'islanded':int(r['islanded']),
    'reserve_requirement_kw':float(r['reserve_requirement_kw']),
    'ev_availability_multiplier':float(r['ev_availability_multiplier']),
    'max_critical_shed_kw':float(r['max_critical_shed_kw']),
} for r in sh_rows}
prob={r['scenario_id']:float(r['probability']) for r in scen_rows}

gens={r['generator_id']:{k:(float(v) if k"'!='"'generator_id' else v) for k,v in r.items()} for r in gen_rows}
for g in gens.values():
    g['min_up_hours']=int(g['min_up_hours']); g['min_down_hours']=int(g['min_down_hours'])
stors={r['storage_id']:{k:(float(v) if k not in ('storage_id','grid_forming') else (int(v) if k=='grid_forming' else v)) for k,v in r.items()} for r in stor_rows}
evs={r['cluster_id']:{k:(float(v) if k not in ('cluster_id','arrival_hour','departure_hour','v2g_allowed') else (int(v) if k in ('arrival_hour','departure_hour','v2g_allowed') else v)) for k,v in r.items()} for r in ev_rows}

# Parse solution rows exactly but floats for numerics
rows=[]
for i,r in enumerate(sol_rows, start=2):
    rr=dict(r)
    rr['_line']=i
    rr['hour']=int(r['hour'])
    for c in ['power_kw','charge_kw','discharge_kw','soc_kwh','curtail_kw','shed_kw','reserve_kw']:
        rr[c]=float(r[c]) if r[c] "'!= '"'' else None
    rows.append(rr)

# Index rows
bykey={}
dup=[]
for r in rows:
    k=(r['row_type'],r['scenario_id'],r['hour'],r['asset_id'])
    if k in bykey:
        dup.append((k,bykey[k]['_line'],r['_line']))
    bykey[k]=r

viol=[]

def add(fam,key,rule,obs,req,suggestion):
    viol.append({'family':fam,'key':key,'rule':rule,'observed':obs,'required':req,'repair':suggestion})

# Schema and key coverage
expected=[]
for s in scenarios:
    for h in hours:
        for rt,assets in row_assets.items():
            for a in assets:
                expected.append((rt,s,h,a))
expected=set(expected)
actual=set(bykey)
missing=sorted(expected-actual)
extra=sorted(actual-expected)
for k in missing[:20]:
    add('schema/key coverage',k,'Required row missing','missing','exactly one row','emit the missing row with valid numeric fields')
for k in extra[:20]:
    add('schema/key coverage',k,'Unexpected row present','present','no extra keys','drop or rename the row to a public key')
for k,l1,l2 in dup[:20]:
    add('schema/key coverage',k,'Duplicate key rows',f'lines {l1} and {l2}','exactly one row per key','deduplicate and keep one public row per key')

# domain/nullability
allowed_row_types=set(row_assets)
allowed_scen=set(scenarios)
for r in rows:
    if r['row_type'] not in allowed_row_types:
        add('identifier domains',(r['_line'],),'Invalid row_type',r['row_type'],sorted(allowed_row_types),'use a public row_type')
    if r['scenario_id'] not in allowed_scen:
        add('identifier domains',(r['_line'],),'Invalid scenario_id',r['scenario_id'],sorted(allowed_scen),'use a public scenario id')
    if r['hour'] not in hours:
        add('identifier domains',(r['_line'],),'Invalid hour',r['hour'],hours,'use an hour in 0..23')
    if r['asset_id'] not in row_assets.get(r['row_type'],[]):
        add('identifier domains',(r['_line'],),'Invalid asset_id for row_type',r['asset_id'],row_assets.get(r['row_type'],[]),'use a public asset id for the row_type')
    # generator commit rule
    if r['row_type']=='generator':
        if r['commit'] not in ('0','1'):
            add('schema/nullability',(r['row_type'],r['scenario_id'],r['hour'],r['asset_id']),'Generator commit must be 0 or 1',r['commit'],'0 or 1','write binary commit on generator rows')
    else:
        if r['commit'] not in ('','0'):
            add('schema/nullability',(r['row_type'],r['scenario_id'],r['hour'],r['asset_id']),'Non-generator commit must be blank or 0',r['commit'],'blank or 0','clear commit on non-generator rows')
    for c in ['power_kw','charge_kw','discharge_kw','soc_kwh','curtail_kw','shed_kw','reserve_kw']:
        if r[c] is None:
            add('schema/nullability',(r['row_type'],r['scenario_id'],r['hour'],r['asset_id']),'Physical columns must be numeric',f'{c}=NULL','nonnegative numeric','populate all physical columns with numeric values')
        elif r[c] < -BIGTOL:
            add('schema/nullability',(r['row_type'],r['scenario_id'],r['hour'],r['asset_id']),'Physical columns must be nonnegative',f'{c}={r[c]}','>= 0','remove negative physical values')

# Nonanticipative generator commitment exact across scenarios
commit_ref={}
for g in G:
    for h in hours:
        vals={s:int(bykey[('generator',s,h,g)]['commit']) for s in scenarios}
        uniq=sorted(set(vals.values()))
        if len(uniq)>1:
            add('frozen/nonanticipative',('generator',h,g),'Generator commitment must be identical across scenarios',vals,'all scenarios same commit','freeze the generator commit to one shared value')
        commit_ref[(g,h)]=uniq[0]

# per-generator commitment pattern and min up/down
for g in G:
    params=gens[g]
    u=[commit_ref[(g,h)] for h in hours]
    init=config['initial_commitment'][g]
    # internal start-up/down checks over horizon given initial state, excluding carry-in ambiguity except logical transitions
    prev=init
    starts=[]; stops=[]
    for h,val in enumerate(u):
        if val-prev==1: starts.append(h)
        if prev-val==1: stops.append(h)
        prev=val
    # min up after every startup completely inside horizon
    mu=params['min_up_hours']
    md=params['min_down_hours']
    for h in starts:
        end=min(23,h+mu-1)
        if any(u[t]"'!=1 for t in range(h,end+1)):
            first=[t for t in range(h,end+1) if u[t]!=1][0]
            add('"'time/non-overlap',('generator',g,h),'Minimum up-time after startup violated',f'start at {h}, commit[{first}]={u[first]}',f'commit=1 through hour {end}','extend on-time after startup or delay the startup')
    for h in stops:
        end=min(23,h+md-1)
        if any(u[t]"'!=0 for t in range(h,end+1)):
            first=[t for t in range(h,end+1) if u[t]!=0][0]
            add('"'time/non-overlap',('generator',g,h),'Minimum down-time after shutdown violated',f'stop at {h}, commit[{first}]={u[first]}',f'commit=0 through hour {end}','extend off-time after shutdown or delay the shutdown')

# scenario-wise checks
scen_cost={s:0.0 for s in scenarios}
# startup/no-load once per scenario to reconstruct scenario cost
for s in scenarios:
    for g in G:
        params=gens[g]
        prev=config['initial_commitment'][g]
        for h in hours:
            row=bykey[('generator',s,h,g)]
            u=int(row['commit'])
            if u-prev==1:
                scen_cost[s]+=params['startup_cost']
            scen_cost[s]+=params['no_load_cost_per_hour']*u
            scen_cost[s]+=params['marginal_cost_per_kwh']*row['power_kw']
            prev=u
    for h in hours:
        gr=bykey[('grid',s,h,'grid')]
        scen_cost[s]+=base[h]['tariff_import_per_kwh']*gr['power_kw']
        for b in B:
            r=bykey[('storage',s,h,b)]
            # throughput-based interpretation
            scen_cost[s]+=stors[b]['cycle_cost_per_kwh']*(r['charge_kw']+r['discharge_kw'])
        for e in E:
            r=bykey[('ev_cluster',s,h,e)]
            scen_cost[s]+=evs[e]['cycle_cost_per_kwh']*(r['charge_kw']+r['discharge_kw'])
        drrow=bykey[('demand_response',s,h,'flex_load')]
        if h in dr:
            scen_cost[s]+=dr[h]['discomfort_cost_per_kwh']*drrow['curtail_kw']
        for ren_id in R:
            rr=bykey[('renewable',s,h,ren_id)]
            scen_cost[s]+=config['renewable_curtailment_cost_per_kwh']*rr['curtail_kw']
        shed=bykey[('load_shed',s,h,'critical_load')]
        scen_cost[s]+=config['load_shed_penalty_per_kwh']*shed['shed_kw']

# common function for start SOC
for s in scenarios:
    # DR consecutive and daily limit
    dr_hours=sorted(dr)
    dr_active=[]
    total_dr=0.0
    rebound=defaultdict(float)
    for h in hours:
        row=bykey[('demand_response',s,h,'flex_load')]
        cur=row['curtail_kw']
        total_dr += cur
        if h not in dr and cur>BIGTOL:
            add('capacities/derates',('demand_response',s,h,'flex_load'),'Demand response only allowed in listed hours',cur,'0 outside eligible hours','set curtailment to zero outside demand_response.csv hours')
        if h in dr:
            if cur - dr[h]['max_curtail_kw'] > BIGTOL:
                add('capacities/derates',('demand_response',s,h,'flex_load'),'Demand-response curtailment exceeds hourly max',cur,dr[h]['max_curtail_kw'],'reduce curtailment to the public hourly cap')
            if cur > BIGTOL:
                dr_active.append(h)
            rebound[dr[h]['rebound_hour']] += dr[h]['rebound_fraction']*cur
        if row['reserve_kw']>BIGTOL or row['power_kw']>BIGTOL or row['charge_kw']>BIGTOL or row['discharge_kw']>BIGTOL or row['shed_kw']>BIGTOL or row['soc_kwh']>BIGTOL:
            pass # no public restriction on unused cols beyond nonnegative numeric
    if total_dr - config['max_daily_dr_kwh'] > BIGTOL:
        add('conservation/inventory',('demand_response',s),'Demand-response daily energy exceeds cap',total_dr,config['max_daily_dr_kwh'],'reduce total daily curtailment')
    max_consec=config['max_consecutive_dr_hours']
    consec=0
    prev=None
    for h in dr_active:
        if prev is not None and h==prev+1:
            consec += 1
        else:
            consec = 1
        if consec > max_consec:
            add('time/non-overlap',('demand_response',s,h),'Demand response exceeds max consecutive hours',f'active run reaches {consec} hours ending at {h}',f'at most {max_consec} consecutive hours','drop curtailment in one hour of the run')
            break
        prev=h

    # Battery checks
    for b in B:
        p=stors[b]
        prev_soc=p['initial_soc_kwh']
        for h in hours:
            r=bykey[('storage',s,h,b)]
            ch,dis,soc,res = r['charge_kw'],r['discharge_kw'],r['soc_kwh'],r['reserve_kw']
            if ch > BIGTOL and dis > BIGTOL:
                add('time/non-overlap',('storage',s,h,b),'Battery cannot charge and discharge simultaneously',f'charge={ch}, discharge={dis}','not both positive','set one of charge/discharge to zero')
            if ch - p['max_charge_kw'] > BIGTOL:
                add('capacities/derates',('storage',s,h,b),'Battery charge exceeds max_charge_kw',ch,p['max_charge_kw'],'reduce charging power')
            if dis - p['max_discharge_kw'] > BIGTOL:
                add('capacities/derates',('storage',s,h,b),'Battery discharge exceeds max_discharge_kw',dis,p['max_discharge_kw'],'reduce discharge power')
            if soc < p['min_soc_kwh'] - BIGTOL or soc > p['max_soc_kwh'] + BIGTOL:
                add('conservation/inventory',('storage',s,h,b),'Battery SOC outside bounds',soc,f\"[{p['min_soc_kwh']}, {p['max_soc_kwh']}]\",'keep SOC within min/max bounds')
            expected_soc=prev_soc + p['charge_efficiency']*ch - dis/p['discharge_efficiency']
            if abs(soc-expected_soc) > 1e-3:
                add('conservation/inventory',('storage',s,h,b),'Battery SOC recursion mismatch',soc,round(expected_soc,6),'recompute SOC from prior state, charge, and discharge')
            prev_soc=soc
        if prev_soc + BIGTOL < p['initial_soc_kwh']:
            add('conservation/inventory',('storage',s,23,b),'Battery terminal SOC below initial',prev_soc,p['initial_soc_kwh'],'end the day at or above initial SOC')

    # EV checks
    for e in E:
        p=evs[e]
        prev_soc=p['initial_soc_kwh']
        for h in hours:
            r=bykey[('ev_cluster',s,h,e)]
            ch,dis,soc,res = r['charge_kw'],r['discharge_kw'],r['soc_kwh'],r['reserve_kw']
            connected = p['arrival_hour'] <= h < p['departure_hour']
            avail = scenh[(s,h)]['ev_availability_multiplier']
            if ch > BIGTOL and dis > BIGTOL:
                add('time/non-overlap',('ev_cluster',s,h,e),'EV cluster cannot charge and discharge simultaneously',f'charge={ch}, discharge={dis}','not both positive','set one of charge/discharge to zero')
            if connected:
                max_ch=avail*p['max_charge_kw']
                max_dis=avail*p['max_discharge_kw'] if p['v2g_allowed'] else 0.0
            else:
                max_ch=max_dis=0.0
                if ch>BIGTOL or dis>BIGTOL or res>BIGTOL:
                    add('time/readiness',('ev_cluster',s,h,e),'EV exchange/reserve outside connection window',f'charge={ch}, discharge={dis}, reserve={res}','all zero while disconnected','zero EV power and reserve outside arrival..departure window')
            if ch - max_ch > BIGTOL:
                add('capacities/derates',('ev_cluster',s,h,e),'EV charging exceeds connection/availability limit',ch,max_ch,'reduce EV charging to the derated limit')
            if dis - max_dis > BIGTOL:
                add('capacities/derates',('ev_cluster',s,h,e),'EV discharging exceeds connection/availability limit',dis,max_dis,'reduce EV discharge to the derated limit')
            if soc < p['min_soc_kwh'] - BIGTOL or soc > p['max_soc_kwh'] + BIGTOL:
                add('conservation/inventory',('ev_cluster',s,h,e),'EV SOC outside bounds',soc,f\"[{p['min_soc_kwh']}, {p['max_soc_kwh']}]\",'keep EV SOC within min/max bounds')
            expected_soc=prev_soc + p['charge_efficiency']*ch - dis/p['discharge_efficiency']
            if abs(soc-expected_soc) > 1e-3:
                add('conservation/inventory',('ev_cluster',s,h,e),'EV SOC recursion mismatch',soc,round(expected_soc,6),'recompute EV SOC from prior state, charge, and discharge')
            prev_soc=soc
        target_hour=p['departure_hour']-1
        if bykey[('ev_cluster',s,target_hour,e)]['soc_kwh'] + BIGTOL < p['target_soc_kwh']:
            add('conservation/inventory',('ev_cluster',s,target_hour,e),'EV departure target not met',bykey[('ev_cluster',s,target_hour,e)]['soc_kwh'],p['target_soc_kwh'],'charge earlier so the departure SOC target holds in every scenario')

    # Generator checks incl dispatch/reserve/ramp, emissions
    emissions=0.0
    gen_reserve_island=0.0
    inertia=0.0
    for g in G:
        p=gens[g]
        prev_power=None
        for h in hours:
            r=bykey[('generator',s,h,g)]
            u=int(r['commit'])
            pw=r['power_kw']; res=r['reserve_kw']
            if u==0 and (pw>BIGTOL or res>BIGTOL):
                add('capacities/derates',('generator',s,h,g),'Generator must be off when not committed',f'power={pw}, reserve={res}','power=0 and reserve=0 when commit=0','zero dispatch and reserve or set commit=1 in all scenarios')
            if u==1:
                if pw + BIGTOL < p['min_kw']:
                    add('capacities/derates',('generator',s,h,g),'Committed generator below minimum output',pw,p['min_kw'],'raise output to at least min_kw or turn the unit off')
                if pw - p['max_kw'] > BIGTOL:
                    add('capacities/derates',('generator',s,h,g),'Generator exceeds max output',pw,p['max_kw'],'reduce output to max_kw')
            if res - (p['max_kw']*u - pw) > BIGTOL:
                add('reserves/ramps',('generator',s,h,g),'Generator reserve exceeds committed headroom',res,p['max_kw']*u - pw,'reduce reserve or dispatch to keep reserve within headroom')
            if res - p['ramp_up_kw'] > BIGTOL:
                add('reserves/ramps',('generator',s,h,g),'Generator reserve exceeds ramp_up_kw',res,p['ramp_up_kw'],'reduce reserve to the ramp-up limit')
            if prev_power is not None:
                if pw - prev_power - p['ramp_up_kw'] > BIGTOL:
                    add('reserves/ramps',('generator',s,h,g),'Generator dispatch ramp-up exceeds limit',pw-prev_power,p['ramp_up_kw'],'smooth dispatch increases across hours')
                if prev_power - pw - p['ramp_down_kw'] > BIGTOL:
                    add('reserves/ramps',('generator',s,h,g),'Generator dispatch ramp-down exceeds limit',prev_power-pw,p['ramp_down_kw'],'smooth dispatch decreases across hours')
            prev_power=pw
            emissions += p['emission_kg_per_kwh']*pw
    if emissions - config['scenario_emissions_cap_kg'] > BIGTOL:
        add('conservation/inventory',('scenario',s),'Scenario emissions exceed cap',emissions,config['scenario_emissions_cap_kg'],'reduce generator output or commit cleaner units')

    # renewable, grid, shed, power balance, reserve aggregation/islanding
    total_inertia_issue=False
    for h in hours:
        sh=scenh[(s,h)]
        load=base[h]['base_load_kw']*sh['load_multiplier']
        gen_sum=sum(bykey[('generator',s,h,g)]['power_kw'] for g in G)
        gen_reserve=sum(bykey[('generator',s,h,g)]['reserve_kw'] for g in G)
        gridrow=bykey[('grid',s,h,'grid')]
        if gridrow['power_kw'] - grid[h]*sh['grid_import_multiplier'] > BIGTOL:
            add('capacities/derates',('grid',s,h,'grid'),'Grid import exceeds derated cap',gridrow['power_kw'],grid[h]*sh['grid_import_multiplier'],'reduce grid import to the scenario-hour cap')
        if sh['islanded'] and gridrow['power_kw'] > BIGTOL:
            add('time/readiness',('grid',s,h,'grid'),'Grid import must be zero during islanding',gridrow['power_kw'],0.0,'set grid import to zero in islanded hours')
        ren_used=0.0
        for rr in R:
            row=bykey[('renewable',s,h,rr)]
            avail=ren[h][rr]*(sh['pv_multiplier'] if rr=='pv' else sh['wind_multiplier'])
            if row['power_kw'] + row['curtail_kw'] - avail > BIGTOL or avail - (row['power_kw']+row['curtail_kw']) > BIGTOL:
                add('capacities/derates',('renewable',s,h,rr),'Renewable used plus curtailment must equal available production',row['power_kw']+row['curtail_kw'],avail,'adjust renewable output and curtailment to match available energy')
            if row['power_kw'] - avail > BIGTOL:
                add('capacities/derates',('renewable',s,h,rr),'Renewable output exceeds scenario-adjusted availability',row['power_kw'],avail,'reduce renewable output to available production')
            ren_used += row['power_kw']
        shed=bykey[('load_shed',s,h,'critical_load')]
        if shed['shed_kw'] - sh['max_critical_shed_kw'] > BIGTOL:
            add('capacities/derates',('load_shed',s,h,'critical_load'),'Critical load shed exceeds scenario-hour cap',shed['shed_kw'],sh['max_critical_shed_kw'],'reduce emergency shedding to the public cap')
        storage_dis=sum(bykey[('storage',s,h,b)]['discharge_kw'] for b in B)
        storage_ch=sum(bykey[('storage',s,h,b)]['charge_kw'] for b in B)
        ev_dis=sum(bykey[('ev_cluster',s,h,e)]['discharge_kw'] for e in E)
        ev_ch=sum(bykey[('ev_cluster',s,h,e)]['charge_kw'] for e in E)
        drcur=bykey[('demand_response',s,h,'flex_load')]['curtail_kw']
        rhs=load + rebound[h] + storage_ch + ev_ch
        lhs=gen_sum + gridrow['power_kw'] + ren_used + storage_dis + ev_dis + drcur + shed['shed_kw']
        if abs(lhs-rhs) > 1e-3:
            add('conservation/inventory',('scenario',s,h),'Power balance mismatch',round(lhs-rhs,6),'0 residual','rebalance generation, storage, DR, and shedding for the scenario-hour')
        reserve_total = gen_reserve + sum(bykey[('storage',s,h,b)]['reserve_kw'] for b in B) + sum(bykey[('ev_cluster',s,h,e)]['reserve_kw'] for e in E)
        if reserve_total + BIGTOL < sh['reserve_requirement_kw']:
            add('reserves/ramps',('scenario',s,h),'Total reserve below scenario-hour requirement',reserve_total,sh['reserve_requirement_kw'],'increase reserve contributions to meet the hourly requirement')
        if sh['islanded']:
            if gen_reserve + BIGTOL < config['island_min_synchronous_reserve_kw']:
                add('reserves/ramps',('scenario',s,h),'Islanded synchronous generator reserve below minimum',gen_reserve,config['island_min_synchronous_reserve_kw'],'commit or unload more synchronous generation during islanding')
            gf_reserve=sum(bykey[('storage',s,h,b)]['reserve_kw'] for b in B if stors[b]['grid_forming'])
            req_gf=config['grid_forming_storage_reserve_fraction']*sh['reserve_requirement_kw']
            if gf_reserve + BIGTOL < req_gf:
                add('reserves/ramps',('scenario',s,h),'Islanded grid-forming storage reserve below required fraction',gf_reserve,req_gf,'increase reserve on grid-forming batteries during islanding')
            inertia=sum(gens[g]['inertia_score']*int(bykey[('generator',s,h,g)]['commit']) for g in G) + sum((stors[b]['inertia_score_per_100kwh']*bykey[('storage',s,h,b)]['soc_kwh']/100.0) for b in B if stors[b]['grid_forming'])
            if inertia + BIGTOL < config['island_min_inertia_score']:
                add('reserves/ramps',('scenario',s,h),'Islanded inertia/grid-forming stability below minimum',inertia,config['island_min_inertia_score'],'keep more synchronous units committed or more grid-forming battery energy online')

# Print summary
print('violation_count', len(viol))
if viol:
    for v in viol[:50]:
        print(v)
else:
    print('No violations found in checked families')
